/**
 * Build the iframe runtime of the SubjectTutor walkthrough widget (ADR 0005 Q1).
 *
 * Each `lib/tutor/runtime/entries/<v>.ts` is bundled to one browser IIFE and written to
 * `lib/tutor/build/generated/runtime-<v>.ts` as `export const RUNTIME_<V> = "<js>";`.
 * Tool: Rollup + rollup-plugin-typescript2 (both root devDependencies; no new dependency).
 *
 * Usage: node scripts/generate-tutor-runtime.mjs [--check]
 *   --check  write nothing; exit 1 if any generated file differs, is missing or is orphaned.
 *
 * Entry contract: <v> matches /^[a-z][a-z0-9-]*$/; the entry is a side-effect script with NO
 * exports (it wires itself to the iframe DOM / postMessage).
 * Fails the build on any Rollup warning, which includes node: / bare imports that cannot be
 * resolved, so Node APIs cannot leak into the iframe. `tsconfig.tutor-runtime.json` has
 * `types: []`, so Node globals (process, Buffer, ...) are also type errors.
 *
 * TODO(1d-01): also bundle `run` + `inputSpec` of one walkthrough entry (lib/subjects/**) into
 * the runtime of its visualizer. Write that as extra entry files that import the entry module;
 * no change to this script is expected because `@/` and `lib/subjects/**` already resolve.
 */
import {
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  unlinkSync,
  writeFileSync,
} from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import prettier from 'prettier';
import { rollup } from 'rollup';
import { nodeResolve } from '@rollup/plugin-node-resolve';
import commonjs from '@rollup/plugin-commonjs';
import typescript from 'rollup-plugin-typescript2';

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const entriesDir = path.join(root, 'lib', 'tutor', 'runtime', 'entries');
const outDir = path.join(root, 'lib', 'tutor', 'build', 'generated');
const HEADER = '// GENERATED by scripts/generate-tutor-runtime.mjs — do not edit';
const check = process.argv.includes('--check');
// rpt2 resolves its cache dir against the cwd, so make the script cwd-independent.
process.chdir(root);

/** Resolve '@/x' to <repo root>/x (same alias as tsconfig.json), then let the other plugins finish. */
const aliasAt = {
  name: 'alias-at',
  resolveId(source, importer, options) {
    if (!source.startsWith('@/')) return null;
    return this.resolve(path.join(root, source.slice(2)), importer, { ...options, skipSelf: true });
  },
};

async function bundle(file) {
  const build = await rollup({
    input: file,
    treeshake: true,
    onwarn(warning) {
      throw new Error(`${path.relative(root, file)}: ${warning.code}: ${warning.message}`);
    },
    plugins: [
      aliasAt,
      nodeResolve({ browser: true, preferBuiltins: false, extensions: ['.ts', '.js', '.json'] }),
      commonjs(),
      // clean: no on-disk cache, so output never depends on a previous run.
      typescript({ tsconfig: path.join(root, 'tsconfig.tutor-runtime.json'), clean: true }),
    ],
  });
  try {
    const { output } = await build.generate({ format: 'iife', exports: 'none', sourcemap: false });
    if (output.length !== 1) throw new Error(`${file}: expected one chunk, got ${output.length}`);
    return output[0].code;
  } finally {
    await build.close();
  }
}

const names = existsSync(entriesDir)
  ? readdirSync(entriesDir)
      .filter((f) => f.endsWith('.ts') && !f.endsWith('.d.ts'))
      .map((f) => f.slice(0, -3))
      .sort()
  : [];
for (const v of names) {
  if (!/^[a-z][a-z0-9-]*$/.test(v)) throw new Error(`Bad entry name "${v}" (want [a-z][a-z0-9-]*)`);
}

const expected = new Map();
for (const v of names) {
  const code = await bundle(path.join(entriesDir, v + '.ts'));
  if (code.includes(root)) throw new Error(`${v}: bundle contains an absolute path`);
  const outFile = path.join(outDir, `runtime-${v}.ts`);
  const constName = `RUNTIME_${v.toUpperCase().replaceAll('-', '_')}`;
  const source = `${HEADER}\nexport const ${constName} = ${JSON.stringify(code)};\n`;
  const config = await prettier.resolveConfig(outFile);
  expected.set(outFile, await prettier.format(source, { ...config, parser: 'typescript' }));
}

// Generated files whose entry is gone (only runtime-*.ts that carry our header).
const orphans = existsSync(outDir)
  ? readdirSync(outDir)
      .filter((f) => /^runtime-.+\.ts$/.test(f))
      .map((f) => path.join(outDir, f))
      .filter((f) => !expected.has(f) && readFileSync(f, 'utf8').startsWith(HEADER))
  : [];

const stale = [...expected].filter(
  ([f, text]) => !existsSync(f) || readFileSync(f, 'utf8') !== text,
);

if (check) {
  const bad = [...stale.map(([f]) => f), ...orphans].map((f) => path.relative(root, f));
  if (bad.length) {
    console.error(
      `[tutor-runtime] out of date (run: pnpm gen:tutor-runtime):\n  ${bad.join('\n  ')}`,
    );
    process.exit(1);
  }
  console.log(`[tutor-runtime] up to date (${names.length} entries)`);
} else {
  mkdirSync(outDir, { recursive: true });
  for (const [f, text] of stale) writeFileSync(f, text);
  for (const f of orphans) unlinkSync(f);
  console.log(
    `[tutor-runtime] wrote ${stale.length}, removed ${orphans.length}, total ${names.length} entries`,
  );
}
